"""Print the fields of an expression."""
import sys

from cronish.parser import parse


def main(argv):
    if len(argv) != 1:
        print("usage: python3 -m cronish 'MINUTE HOUR WEEKDAY'", file=sys.stderr)
        return 2
    try:
        schedule = parse(argv[0])
    except ValueError as err:
        print(f"error: {err}", file=sys.stderr)
        return 1
    print("minutes:", sorted(schedule.minutes))
    print("hours:", sorted(schedule.hours))
    print("weekdays:", sorted(schedule.weekdays))
    return 0


raise SystemExit(main(sys.argv[1:]))
"""Parsing schedule expressions."""
from collections import namedtuple

Schedule = namedtuple("Schedule", "minutes hours weekdays")


def parse_field(text, low, high, name):
    """Expand one field (`*`, `N`, `A-B`, `*/N` or a comma list) into a set of ints."""
    values = set()
    for part in text.split(","):
        step = 1
        if "/" in part:
            part, step_text = part.split("/", 1)
            step = int(step_text)
        if part == "*":
            start, end = low, high
        elif "-" in part:
            start, end = (int(x) for x in part.split("-", 1))
        else:
            start = end = int(part)
        if name == "weekday" and end == 7:
            raise ValueError("weekday 7 is not accepted; Sunday is 0")
        if start < low or end > high or start > end:
            raise ValueError(f"{name} {part!r} is out of range {low}-{high}")
        values.update(range(start, end + 1, step))
    return values


def parse(expr):
    """Parse `MINUTE HOUR WEEKDAY` into a Schedule."""
    fields = expr.split()
    if len(fields) != 3:
        raise ValueError(f"expected 3 fields, found {len(fields)}")
    return Schedule(parse_field(fields[0], 0, 59, "minute"),
                    parse_field(fields[1], 0, 23, "hour"),
                    parse_field(fields[2], 0, 6, "weekday"))
import unittest

from cronish.parser import parse, parse_field


class ParserTests(unittest.TestCase):
    def test_star_covers_the_range(self):
        self.assertEqual(parse_field("*", 0, 5, "minute"), {0, 1, 2, 3, 4, 5})

    def test_step_over_a_range(self):
        self.assertEqual(parse_field("10-20/5", 0, 59, "minute"), {10, 15, 20})

    def test_three_fields_are_required(self):
        with self.assertRaises(ValueError):
            parse("* *")

    def test_out_of_range_minute(self):
        with self.assertRaises(ValueError):
            parse("61 * *")


if __name__ == "__main__":
    unittest.main()

